#' Validate file uploads
#' @param file Uploaded file object
#' @param required_cols Required column names
#' @param file_type Type of file for error messages
#' @return TRUE if valid, throws error if invalid
validate_file_upload <- function(file, required_cols = NULL, file_type = "file") {
  if (is.null(file)) {
    stop(paste("❌ No", file_type, "uploaded"))
  }

  if (file$size == 0) {
    stop(paste("❌", file_type, "file is empty"))
  }

  # Try to read the file
  tryCatch({
    df <- readr::read_table(file$datapath)
    if (nrow(df) == 0) {
      stop(paste("❌", file_type, "file contains no data"))
    }

    # Check required columns if specified
    if (!is.null(required_cols)) {
      missing_cols <- setdiff(required_cols, names(df))
      if (length(missing_cols) > 0) {
        stop(paste("❌", file_type, "missing required columns:", paste(missing_cols, collapse = ", ")))
      }
    }

    TRUE
  }, error = function(e) {
    stop(paste("❌ Error reading", file_type, ":", e$message))
  })
}

